mapper.select:
SELECT a.id, a.category_id, a.title, a.slug, a.content, a.description, a.cover_image, a.tags, a.status, a.source, a.dataset_id, a.km_document_id, a.source_path, a.content_hash, a.published_at, a.view_count, a.create_time, a.update_time, c.name AS category_name, c.path AS category_path, c.source AS category_source FROM km_blog_article a LEFT JOIN km_blog_category c ON a.category_id = c.id AND c.del_flag = '0' WHERE a.del_flag = '0'
AND ${ew.sqlSegment}
ORDER BY a.published_at DESC, a.create_time DESC

mapper.update:
UPDATE km_blog_article
SET view_count = view_count + #{delta}
WHERE id = #{articleId}
